### Dual-Peripheral Electrical Ping Verification

Before running full graphics and clock libraries, let's run an electrical health-check sketch. This program verifies that both devices are receiving power, sharing ground, and acknowledging their addresses over the breadboard rails:

```cpp
#include <Wire.h>

const byte LCD_ADDRESS = 0x27; // PCF8574 Backpack
const byte RTC_ADDRESS = 0x68; // DS3231 Real-Time Clock

void setup() {
  Wire.begin();
  Serial.begin(9600);
  while (!Serial); // Wait for Serial Monitor

  Serial.println("========================================");
  Serial.println("   DUAL-DEVICE BUS CONTINUITY CHECKER   ");
  Serial.println("========================================");

  checkPeripheral("16x2 Character LCD", LCD_ADDRESS);
  checkPeripheral("DS3231 Real-Time Clock", RTC_ADDRESS);

  Serial.println("\nAll bus rails checked! Ready for telemetry.");
}

void checkPeripheral(const char* name, byte address) {
  Serial.print("Probing ");
  Serial.print(name);
  Serial.print(" at 0x");
  if (address < 16) Serial.print('0');
  Serial.print(address, HEX);
  Serial.print("... ");

  Wire.beginTransmission(address);
  byte status = Wire.endTransmission();

  if (status == 0) {
    Serial.println("[OK] - Acknowledged! Electrical continuity confirmed.");
  } else if (status == 2) {
    Serial.println("[NACK] - Address not found. Check SDA/SCL breadboard rows!");
  } else if (status == 4) {
    Serial.println("[BUS ERROR] - Hardware contention or short circuit!");
  } else {
    Serial.print("[FAIL] - Code: ");
    Serial.println(status);
  }
}

void loop() {
  // Run once in setup; idle in loop
}
```

### Code Deconstruction:
- `Wire.beginTransmission(address)`: Sends the target address byte across Row 20 (SDA) and Row 21 (SCL).
- `Wire.endTransmission()`: If the device is properly powered and wired in parallel, its internal FET pulls Row 20 LOW on clock 9, returning code `0`.
- Error handling: Returns code `2` (Address NACK) if a jumper wire in Row 20 or Row 21 is unplugged.

